//////
/// 
/// $INTERFACE VDCM                    biu              (4,4)
///     ###
///     * Register specification of interface Inverse Tone Mapping Operator
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 CFG0                 (P)
///               %unsigned 1  FRbypass                  0x0
///                                    ###
///                                    * Bypass Full range Logic, No delay change
///                                    ###
///               %unsigned 1  SNRbypass                 0x0
///                                    ###
///                                    * Bypass SNR block, Involves 1line+Module delay change
///                                    ###
///               %unsigned 1  IOETFbypass               0x0
///                                    ###
///                                    * EOTF bypass, No delay change
///                                    ###
///               %unsigned 1  CMPbypass                 0x0
///                                    ###
///                                    * Color Remap bypass, Involves Module delay change
///                                    ###
///               %unsigned 1  IEOTFbypass               0x0
///                                    ###
///                                    * OETF bypass, No delay change
///                                    ###
///               %%        27         # Stuffing bits...
///     @ 0x00004 CFG1                 (P)
///               %unsigned 12 min                       0x100
///                                    ###
///                                    * Input lower bound
///                                    ###
///               %unsigned 12 max                       0xEB0
///                                    ###
///                                    * Input Upper bound
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00008 CFG2                 (P)
///               %unsigned 12 ofs                       0x7D8
///                                    ###
///                                    * Range Offset
///                                    ###
///               %unsigned 13 gain                      0x12B6
///                                    ###
///                                    * Range gain
///                                    ###
///               %%        7          # Stuffing bits...
///     @ 0x0000C CFG3                 (P)
///               %unsigned 10 snrgain                   0xFF
///                                    ###
///                                    * SNR gain
///                                    ###
///               %unsigned 10 snrlimit                  0x3E8
///                                    ###
///                                    * SNR Threshold
///                                    ###
///               %unsigned 8  snrofs                    0xA0
///                                    ###
///                                    * SNR Offset
///                                    ###
///               %%        4          # Stuffing bits...
///     @ 0x00010 CFG4                 (P)
///               %unsigned 11 ghue                      0x0
///                                    ###
///                                    * Global Hue control
///                                    ###
///               %unsigned 12 gsat                      0x0
///                                    ###
///                                    * Global Sturation control
///                                    ###
///               %%        9          # Stuffing bits...
///     @ 0x00014 CFG5                 (P)
///               %unsigned 12 glgt                      0x0
///                                    ###
///                                    * Global Luminance control
///                                    ###
///               %%        20         # Stuffing bits...
///     @ 0x00018 HWIN                 (P)
///               %unsigned 13 STR                       0x0
///                                    ###
///                                    * Area of interest/demo video Horizontal Start point
///                                    ###
///               %unsigned 13 END                       0x0
///                                    ###
///                                    * Area of interest/demo video Horizontal End point
///                                    ###
///               %%        6          # Stuffing bits...
///     @ 0x0001C VWIN                 (P)
///               %unsigned 13 STR                       0x0
///                                    ###
///                                    * Area of interest/demo video Vertical Start point
///                                    ###
///               %unsigned 13 END                       0x0
///                                    ###
///                                    * Area of interest/demo video Vertical End point
///                                    ###
///               %%        6          # Stuffing bits...
///     @ 0x00020 CAOI                 (P)
///               %unsigned 16 UBLK                      0x0
///                                    ###
///                                    * Out of AOI area U forced value
///                                    ###
///               %unsigned 16 VBLK                      0x0
///                                    ###
///                                    * Out of AOI area V forced value
///                                    ###
///     @ 0x00024 YAOI                 (P)
///               %unsigned 16 YBLK                      0x0
///                                    ###
///                                    * Out of AOI area Y forced value
///                                    ###
///               %unsigned 1  aoi_enb                   0x0
///                                    ###
///                                    * 1: Enable AOI processing 1: Normal processing
///                                    ###
///               %unsigned 1  demomode                  0x0
///                                    ###
///                                    * 1: Enable Demo mode 0: Disable Demo mode
///                                    ###
///               %unsigned 1  snrbypass                 0x0
///                                    ###
///                                    * 1: SNR in bypass mode 0: SNR in normal mode
///                                    ###
///               %%        13         # Stuffing bits...
///     @ 0x00028                      (P)
///     # 0x00028 IY2R                 
///               $CSC_C15O18F12       IY2R              REG          
///                                    ###
///                                    * Input Side Full matrix Colorspace conversion Settings
///                                    * 15bits Signed magnitude Coefficients
///                                    * 18bits Signed Magnitude Offset values
///                                    * each with 12bits Fraction bits
///                                    * POD values are set to YUV to RGB in BT.709
///                                    ###
///     @ 0x00048                      (P)
///     # 0x00048 CR2Y                 
///               $CSC_C13O18F12       CR2Y              REG          
///                                    ###
///                                    * Color Remaping- Input Side Full matrix Colorspace conversion Settings
///                                    * 13bits Signed magnitude Coefficients
///                                    * 18bits Signed Magnitude Offset values
///                                    * each with 12bits Fraction bits.
///                                    * POD values are set to RGB to YUV in BT.709
///                                    ###
///     @ 0x00068                      (P)
///     # 0x00068 CY2R                 
///               $CSC_C15O18F12       CY2R              REG          
///                                    ###
///                                    * Color Remaping- Output Side Full matrix Colorspace conversion Settings
///                                    * 15bits Signed magnitude Coefficients
///                                    * 18bits Signed Magnitude Offset values
///                                    * each with 12bits Fraction bits.
///                                    * POD values are set to YUV to RGB in BT.709
///                                    ###
///     @ 0x00088                      (P)
///     # 0x00088 OR2Y                 
///               $CSC_C13O18F12       OR2Y              REG          
///                                    ###
///                                    * Output Side Full matrix Colorspace conversion Settings
///                                    * 13bits Signed magnitude Coefficients
///                                    * 18bits Signed Magnitude Offset values
///                                    * each with 12bits Fraction bits.
///                                    * POD values are set to RGB to YUV in BT.709
///                                    ###
///     @ 0x000A8                      (P)
///     # 0x000A8 YTHR                 
///               $YSCNT               YTHR              REG          
///                                    ###
///                                    * programmable Luminance data input threshold for 2D LUT, [0 to 30] array, 10bit control
///                                    * PoweOnDefault values are not set by Hardware, need to be programmed by firmware initialization.
///                                    * Default: 32 64 96 128 160 192 224 256 288 320 352 384 416 448 480 512 544 576 608 640 672 704 736 768 800 832 864 896 928 960 992
///                                    * Note: Difference between consecutive values should be in the range of 8 to 255
///                                    ###
///     @ 0x000D4                      (P)
///     # 0x000D4 YGAIN                
///               $YSCNT               YGAIN             REG          
///                                    ###
///                                    * programmable Luminance data output gain for 2D LUT, [0 to 31] array, 10bit control.
///                                    * PoweOnDefault values are not set by Hardware, need to be programmed by firmware initialization.
///                                    * Default: All 512
///                                    ###
///     @ 0x00100                      (P)
///     # 0x00100 STHR                 
///               $YSCNT               STHR              REG          
///                                    ###
///                                    * programmable Saturation data input threshold for 2D LUT, [0 to 30] array, 10bit control.
///                                    * PoweOnDefault values are not set by Hardware, need to be programmed by firmware initialization.
///                                    * Default: 32 64 96 128 160 192 224 256 288 320 352 384 416 448 480 512 544 576 608 640 672 704 736 768 800 832 864 896 928 960 992
///                                    * Note: Difference between consecutive values should be in the range of 8 to 255
///                                    ###
///     @ 0x0012C                      (P)
///     # 0x0012C SGAIN                
///               $YSCNT               SGAIN             REG          
///                                    ###
///                                    * programmable Saturation data output gain for 2D LUT, [0 to 31] array, 10bit control.
///                                    * PoweOnDefault values are not set by Hardware, need to be programmed by firmware initialization.
///                                    * Default: All 512
///                                    * IOETF
///                                    * IOETF LUT is moved out of the VDCM IP and placed in Common HDR LUT bank 0.
///                                    * Please see the Common HDR LUT bank (HDRLUT) register sepc documentation.
///                                    * Input side Inverse OETF LUT = EOTF LUT (InEOTF_LUT[] from C model) [0 to 256] array, 14bit LUT values.
///                                    * 2 LUT samples are packed and stored in 32bit address location
///                                    * ={2'h0,IOETF_ODD[13:0],2'h0,IOETF_EVEN[13:0]}
///                                    * Programing is done by firmware based on HDR input format.[HLG,HDR10,SDR] .
///                                    * PoweOnDefault values are not set by Hardware, need to be programmed by firmware initialization.
///                                    * IEOTF
///                                    * IEOTF LUT is moved out of the VDCM IP and placed in Common HDR LUT bank 1.
///                                    * Please see the Common HDR LUT bank (HDRLUT) register sepc documentation.
///                                    * Output side Inverse EOTF LUT = OETF LUT (OutOETF_LUT[] from C model) [0 to 256] array, 14bit LUT values
///                                    * 2 LUT samples are packed and stored in 32bit address location
///                                    * ={2'h0,IEOTF_ODD[13:0],2'h0,IEOTF_EVEN[13:0]}
///                                    * Programing is done by firmware based on HDR output format.[HLG,HDR10,SDR] .
///                                    * PoweOnDefault values are not set by Hardware, need to be programmed by firmware initialization.
///                                    * LUT2D
///                                    * LUT2D LUT is moved out of the VDCM IP and placed in Common HDR LUT bank 2.
///                                    * Please see the Common HDR LUT bank (HDRLUT) register specification documentation.
///                                    * YUV color remapping (LSH to YUV mapping) LUT, 1089 Memory locations with 36 bit each.
///                                    * LUTs are stored in 4 Segments
///                                    * Segment0,289 locations= ((addr[9:0]>=0) &(addr[9:0]<289))
///                                    * Segment1,272 locations= ((addr[9:0]>=289) &(addr[9:0]<561))
///                                    * Segment2,272 locations= ((addr[9:0]>=561)&(addr[9:0]<833))
///                                    * Segment3,256 locations= ((addr[9:0]>=833)&(addr[9:0]<1089))
///                                    * PoweOnDefault values are not set by Hardware, need to be programmed by firmware initialization.
///                                    ###
///     @ 0x00158 RDET                 (P)
///               %unsigned 12 MINTHR                    0xF
///                                    ###
///                                    * Global minimum calculation lower threshold
///                                    ###
///               %unsigned 12 MAXTHR                    0xF
///                                    ###
///                                    * Global maximum calculation higher threshold
///                                    ###
///               %unsigned 1  SEL                       0x1
///                                    ###
///                                    * Input selection for Global range calculation(Yi_sel)
///                                    * VDCM Mode:
///                                    * 0:RGB max from Output of YUVtGBR (vDCM RGB input)
///                                    * 1: Luminance value from Direct YUV vDCM input
///                                    * GDCM Mode:
///                                    * 0: RGB max of direct RGB input
///                                    * 1: Luminance value from input RGB(converted by GBR to Y)
///                                    ###
///               %%        7          # Stuffing bits...
///     @ 0x0015C HHIST                (P)
///               %unsigned 13 STR                       0x0
///                                    ###
///                                    * Area of interest/demo video Horizontal Start point
///                                    ###
///               %unsigned 13 END                       0x780
///                                    ###
///                                    * Area of interest/demo video Horizontal End point
///                                    ###
///               %%        6          # Stuffing bits...
///     @ 0x00160 VHIST                (P)
///               %unsigned 13 STR                       0x0
///                                    ###
///                                    * Area of interest video Vertical Start point for Histogram
///                                    ###
///               %unsigned 13 END                       0x438
///                                    ###
///                                    * Area of interest video Vertical End point for Histogram
///                                    ###
///               %unsigned 2  SEL                       0x0
///                                    ###
///                                    * Histogram selection ({Out_sel,Yo_sel})
///                                    * 00: Output of IOETF
///                                    * 01: Output of GBRtoYUV (CMAP input)
///                                    * 10:Output of YUVtoGBR (Input of IEOTF)
///                                    * 11: Output of CMAPping
///                                    ###
///               %unsigned 1  AOI                       0x1
///                                    ###
///                                    * Enable area of interest setting for histogram
///                                    * 0: Full frame for histogram
///                                    * 1: Active zone histogram set by HHIST and VHIST
///                                    ###
///               %unsigned 1  INITSEL                   0x1
///                                    ###
///                                    * Histogram LUT initialization slot selection
///                                    * 1: Enable SRAM initialization during FRST
///                                    * 0: Enable SRAM initialization after CDF calculation
///                                    ###
///               %unsigned 1  MANCDF                    0x0
///                                    ###
///                                    * CDF calculation trigger setting.
///                                    * 1: Manual CDF trigger, ensure CDF calculation is triggered in Vertical blank (before Frame start)
///                                    * 0: Auto CDF trigger, done during end of Frame.
///                                    ###
///               %%        1          # Stuffing bits...
///     @ 0x00164 HISTC                (P)
///               %unsigned 1  START                     0x0
///                                    ###
///                                    * Used as Histogram CDF calculation start bit, only when MANCDF is 1.
///                                    * The write 1 to this register to kick start the hardware CDF calculation.
///                                    * 0 : No effect on hardware.
///                                    * 1 : start the CDF calculation,
///                                    * NOTE: Ensure CDF calculation is triggered in Vertical blank (before Frame start). It takes 128 clocks to generate CDF after the trigger.
///                                    ###
///               %%        31         # Stuffing bits...
///     @ 0x00168 RESO                 (P)
///               %unsigned 13 HORZ                      0x780
///                                    ###
///                                    * Active Horizontal Pixels
///                                    ###
///               %unsigned 13 VERT                      0x438
///                                    ###
///                                    * Active Vertical Lines
///                                    ###
///               %%        6          # Stuffing bits...
///     @ 0x0016C VACT                 (P)
///               %unsigned 13 STRT                      0x80
///                                    ###
///                                    * Start of Active video from “Frame start”
///                                    * Minimum Vblank back porch required after “frame start” for the Histogram LUT update to firmware and to Clear the LUT before starting new histogram calculation.
///                                    ###
///               %unsigned 2  CLKEN                     0x0
///                                    ###
///                                    * Clock Enable Controls to Timer
///                                    ###
///               %%        17         # Stuffing bits...
///     @ 0x00170 GBL0                 (R-)
///               %unsigned 12 MIN                       
///                                    ###
///                                    * Global Range minimum
///                                    ###
///               %unsigned 12 MAX                       
///                                    ###
///                                    * Global range maximum
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00174 GBL1                 (R-)
///               %unsigned 24 MINCNT                    
///                                    ###
///                                    * Global range minimum count
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00178 GBL2                 (R-)
///               %unsigned 24 MAXCNT                    
///                                    ###
///                                    * Global range maximum count
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x0017C HBUFF                (R-)
///               %unsigned 1  RD                        
///                                    ###
///                                    * Status flag to indicate CPU to read histogram after HW calculation done.
///                                    * Status bit goes HIGH after completing the CDF calculation that takes about 128 clocks of Vertical Blank interval from Frame Reset pulse.
