    #define   SET16HDRLUT_RAM_hdr_sel(r16,v)                   _BFSET_(r16, 6, 4,v)

    #define     w32HDRLUT_RAM                                  {\
            UNSG32 uRAM_rw_en                                  :  1;\
            UNSG32 uRAM_rd_sel                                 :  3;\
            UNSG32 uRAM_hdr_sel                                :  3;\
            UNSG32 RSVDx0_b7                                   : 25;\
          }
    union { UNSG32 u32HDRLUT_RAM;
            struct w32HDRLUT_RAM;
          };
    ///////////////////////////////////////////////////////////
             UNSG8 RSVDx4                                      [2044];
    ///////////////////////////////////////////////////////////
              SIE_OELUT                                        ie_BANK0;
             UNSG8 RSVD_BANK0                                  [512];
    ///////////////////////////////////////////////////////////
              SIE_OELUT                                        ie_BANK1;
             UNSG8 RSVD_BANK1                                  [512];
    ///////////////////////////////////////////////////////////
             UNSG8 RSVDx1800                                   [2048];
    ///////////////////////////////////////////////////////////
              SIE_WDLUT                                        ie_BANK2;
             UNSG8 RSVD_BANK2                                  [3776];
    ///////////////////////////////////////////////////////////
              SIE_D2LUT                                        ie_BANK3;
