//////
/// 
/// $INTERFACE GDET                    biu              (4,4)
///     ###
///     * Register specification of interface IGDET
///     * Defines the size of the igdet
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 CFG0                 (P)
///               %unsigned 1  switch                    0x0
///                                    ###
///                                    * 0: new EE
///                                    * 1: current EE or hard bypass if only new EE is compiled
///                                    ###
///               %unsigned 1  gdet_en                   0x1
///                                    ###
///                                    * 1:Detail ∆Ydet output is enabled
///                                    * 0: ∆Ydet output is disabled
///                                    ###
///               %unsigned 1  gdet_add                  0x0
///                                    ###
///                                    * Controls Ydet output: 1:Ydet=Yin+∆Ydet
///                                    * 0: Ydet=Yin
///                                    ###
///               %unsigned 1  ups_en                    0x1
///                                    ###
///                                    * 0: Disables 422 to 444 upsampler
///                                    * 1: Enables 422 to 444 upsampler
///                                    ###
///               %unsigned 2  win_r                     0x2
///                                    ###
///                                    * Window radius for calculating neighborhood variance and mean. Can only be 1 or 2. (no other values)
///                                    ###
///               %unsigned 24 eps                       0x28E4
///                                    ###
///                                    * Regulation parameter in guided filter
///                                    ###
///               %%        2          # Stuffing bits...
///     @ 0x00004 CFG1                 (P)
///               %unsigned 12 scale                     0x30
///                                    ###
///                                    * Scale in detail gain calculation
///                                    ###
///               %unsigned 10 mid                       0xC8
///                                    ###
///                                    * MID in detail gain calculation
///                                    ###
///               %unsigned 4  sigma_s1                  0xA
