//////
/// 
/// $INTERFACE EE_TOP                  biu              (4,4)
///     ###
///     * Register specification of interface EE8_TOP
///     * Defines the size of the EE8_TOP
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 CFG0                 (P)
///               %unsigned 8  ctrl                      0x0
///                                    ###
///                                    * ups_en[0]:
///                                    * RESEVED
///                                    * lti_en[1]:
///                                    * 0: LTI disabled
///                                    * 1: LTI enabled
///                                    * det_en[2]:
///                                    * 1: Detail signal is added to the EE output
///                                    * 0. Detail signal is not added to the EE output
///                                    * cti_en[3]:
///                                    * 0: CTI disabled
///                                    * 1: CTI enabled
///                                    * ft_ltien_regs[4]
///                                    * 1: Enable Flesh tone adjustment on lti output.
///                                    *  0: Disable Flesh tone adjustment on lti output.
///                                    * ft_deten_regs[5]
///                                    * 1: Enable fleshtone adjustment on detailed output.
///                                    * 0: Disable Fleshtone adjustment on detailed output.
///                                    * new_lti_algo_sel[6]
///                                    * 0 : disable New algo for lti
///                                    * 1 : enable New algo for lti
///                                    * new_cti_algo_sel[7]
///                                    * 0 : disable New algo for cti
///                                    * 1 : enable New algo for cti
///                                    ###
///               %unsigned 8  lti_gain                  0x40
///                                    ###
///                                    * Value of LTI gain
///                                    ###
///               %unsigned 8  cti_gain                  0x40
///                                    ###
///                                    * Value of CTI gain
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00004 CFG1                 (P)
///               %unsigned 9  ftd_inlow                 0x6E
///                                    ###
///                                    * Lower hue bound of inner skin tone region
///                                    ###
///               %unsigned 9  ftd_inhigh                0x8C
///                                    ###
///                                    * Upper hue bound of inner skin tone region
///                                    ###
///               %unsigned 9  ftd_outlow                0x5F
///                                    ###
///                                    * Upper hue bound of outer skin tone region
///                                    ###
///               %%        5          # Stuffing bits...
///     @ 0x00008 CFG2                 (P)
///               %unsigned 9  ftd_outhigh               0x9B
///                                    ###
///                                    * Upper hue bound of outer skin tone region
///                                    ###
///               %unsigned 8  ftd_ylow                  0x0
///                                    ###
///                                    * Lower bound of luma for skin detection
///                                    ###
///               %unsigned 8  ftd_yhigh                 0xFF
///                                    ###
///                                    * Upper bound of luma for skin detection
///                                    ###
///               %%        7          # Stuffing bits...
///     @ 0x0000C CFG3                 (P)
///               %unsigned 16 ftd_outchroma_low         0x64
///                                    ###
///                                    * Lower chroma bound of outer skin tone region
///                                    ###
///               %unsigned 16 ftd_inchroma_low          0x514
///                                    ###
///                                    * Lower chroma bound of inner skin tone region
///                                    ###
///     @ 0x00010 CFG4                 (P)
///               %unsigned 16 ftd_inchroma_high         0x8FC
///                                    ###
///                                    * Higher chroma bound of inner skin tone region
///                                    ###
///               %unsigned 16 ftd_outchroma_high        0xDAC
///                                    ###
///                                    * Higher chroma bound of outer skin tone region
///                                    ###
///     @ 0x00014 CFG5                 (P)
///               %unsigned 12 ftd_huewidth              0x111
///                                    ###
///                                    * Must be programmed to 4095 / (FTDC_INLOW – FTDC_OUTLOW)
///                                    ###
