//////
/// 
/// $INTERFACE ACE                     biu              (4,4)
///     ###
///     * Register specification of interface ACE
///     * Defines the size of the ace
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 CFG0                 (P)
///               %unsigned 5  EN                        0x0
///                                    ###
///                                    * Bit[0]: en -
///                                    * 0 – disable ACE
///                                    * 1 – enable ACE
///                                    * Bit[3:1]: cc - Three bit number used to program level of color compensation
///                                    * 0 – Disable
///                                    * 7 – Maximum color compensation
///                                    * Bit[4]: crush - When the ACE block gets a cropped DE signal, enabling this bit forces pixels outside the cropped DE to a single value which is in register CMU_ACE_M_OP0.
///                                    ###
///               %unsigned 5  WFG1                      0xC
///                                    ###
///                                    * Weighting factors towards enhanced output for dark region. Can take values from 0 to 31.
///                                    ###
///               %unsigned 5  WFG2                      0x8
///                                    ###
///                                    * Weighting factors towards enhanced output for mid region. Can take values from 0 to 31.
///                                    ###
///               %unsigned 5  WFG3                      0x2
///                                    ###
///                                    * Weighting factors towards enhanced output for bright region. Can take values from 0 to 31.
///                                    ###
///               %%        12         # Stuffing bits...
///     @ 0x00004 CFG1                 (P)
///               %unsigned 12 GB2                       0xF0
///                                    ###
///                                    * Width of guard band regions for dark-mid region boundaries.
///                                    ###
///               %unsigned 12 GB3                       0xA0
///                                    ###
///                                    * Width of guard band regions for mid-bright region boundaries.
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00008 CFG2                 (P)
///               %unsigned 8  MS1                       0x30
///                                    ###
///                                    * Maximum slope value for dark region.
///                                    ###
///               %unsigned 8  MS2                       0x28
///                                    ###
///                                    * Maximum slope value for mid region.
///                                    ###
///               %unsigned 8  MS3                       0x20
///                                    ###
///                                    * Maximum slope value for bright region.
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x0000C CFG3                 (P)
///               %unsigned 12 TH0                       0x0
///                                    ###
///                                    * Thresholds for ACE operation. Can take value between 0 and 4095.
///                                    ###
///               %unsigned 12 TH1                       0x100
///                                    ###
///                                    * Thresholds for ACE operation. Can take value between 0 and 4095.
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00010 CFG4                 (P)
///               %unsigned 12 TH2                       0x590
///                                    ###
///                                    * Thresholds for ACE operation. Can take value between 0 and 4095.
///                                    ###
///               %unsigned 12 TH3                       0xA20
///                                    ###
///                                    * Thresholds for ACE operation. Can take value between 0 and 4095.
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00014 CFG5                 (P)
///               %unsigned 12 TH4                       0xEB0
///                                    ###
///                                    * Thresholds for ACE operation. Can take value between 0 and 4095.
///                                    ###
///               %unsigned 12 TH5                       0xFFF
///                                    ###
///                                    * Thresholds for ACE operation. Can take value between 0 and 4095.
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00018 CFG6                 (P)
///               %unsigned 12 OP0                       0x0
///                                    ###
///                                    * Output luminance value in dark crush region.
///                                    ###
///               %unsigned 12 OP5                       0xFFF
///                                    ###
///                                    * Output luminance value in white pull-up region.
///                                    ###
///               %unsigned 8  MODE                      0x0
///                                    ###
///                                    * Common for MAIN and PIP. Firmware intervention required based on Base, Main and Pip resolutions.
///                                    * Bit[0]: ACE Histogram processing option for 4kx2k mode at 600MHz speed. Set based on base resolution.
///                                    * 0 – upto 1080p
///                                    * 1 – supports 4kx2k display resolution
///                                    * Bit[1]: let_box - Manual letter box selection
///                                    * 0 – Considered all the rows while processing Brightness and ACE
///                                    * 1 – Excludes the top and bottom rows set in the CMU_BR_ACE_ROW register while processing Brightness and ACE.
///                                    * Bit[2]: letbox_auto_man_sel -
///                                    * 0 – Total number of rows in the display will be calculated internally.
///                                    * 1 – Total number of rows in the display need to be programmed in the register CMU_BR_ACE_TOT_ROW.
///                                    * Bit[3]: Reserved
///                                    * Bit[4]: Set when Main Vsize is more than HD
///                                    * 1:Main Histogram & Histogram measure taking vertical sample by2
///                                    * 0:Main Histogram measure taking vertical full scale Set based on Main vertical resolution.
///                                    * Bit[5]: Set when Pip Vsize is more than HD
///                                    * 1:Pip Histogram & Histogram measure taking vertical sample by2
///                                    * 0:Pip Histogram measure taking vertical full scale
///                                    * Bit[6]: Set when Main Hsize is more than HD
///                                    * 1:Main Brightness measure taking Horizontal sample by2
///                                    * 0:Main Brightness & Histogram measure taking Horizontal full scale
///                                    * Bit[7]: Set when Pip Hsize is more than HD
///                                    * 1:Pip Brightness measure taking Horizontal sample by2
///                                    * 0:Pip Brightness & Histogram measure taking Horizontal full scale
///                                    ###
///     @ 0x0001C CFG7                 (P)
///               %unsigned 9  MEM_ADDR                  0x0
///                                    ###
///                                    * Memory address to read Image Histogram during blanking time. Memory address location from 0 to 255 for main.
///                                    ###
///               %%        23         # Stuffing bits...
///     @ 0x00020 CFG8                 (P)
///               %unsigned 16 MEM_RD_END_CNT            0x4000
///                                    ###
///                                    * Common for MAIN and PIP
///                                    * Setting this register to 0, Histogram read option is disabled.
///                                    * Programming this register to 32767 (0x7FFF) gives the sufficient time to read the histogram data from the memory for both main and pip path. During the VBI time, an interrupt will be set to one and this will be reflected in the status register MEM_STATUS, CPU can access the memory contents during this time.
///                                    ###
///               %%        16         # Stuffing bits...
///     @ 0x00024 STS0                 (R-)
///               %unsigned 24 MEM_DATA                  0x0
///                                    ###
///                                    * Histogram data readout from the memory corresponds to Main when the memory address MEM_ADD is placed between 0 to 255. Similarly for the pip memory data can be accessed when the memory address MEM_ADD is between 256 to 511. This is valid only when memory read interrupt status register to the CPU INTR_MEM_RD (MEM_STATUS) is high.
///                                    ###
///               %unsigned 1  INTR_MEM_RD               0x0
///                                    ###
///                                    * CPU can read histogram data from the memories when this register is set.
///                                    * End of ace register group
///                                    ###
///               %%        7          # Stuffing bits...
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:      40B, bits:     222b, padding:     0B
