/// $INTERFACE AC                      biu              (4,4)
///     ###
///     * Register specification of interface AC
///     * Defines the size of the ac
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 CFG0                 (P)
///               ###
///               * Auto color mode control registers for the main path.
///               ###
///               %unsigned 12 MODE                      0x18
///                                    ###
///                                    * Bit[1:0]: chroma_sat - Sets the user defined chroma depth from 0 to 3. 0 means less color enhancement 3 is highest possible w.r.t to the color information in the image.
///                                    * Bit[3:2]: chroma_depth - Controls the color depth saturation between 1 to 2.
///                                    * Bit[4]: bw_val - Disable the auto color mode automatically for the black and white images if this bit is set.
///                                    * Bit[7:5]: color_depth - Sets the auto color enhancement level by choosing between 0 to 4.
///                                    * 0 is the lower auto color threshold and 4 is the highest possible means it makes it very color full.
///                                    * Bit[8]: read_sel -
///                                    * 0 : Main path auto color control debug values can be read
///                                    * 1 : Pip path auto color control debug values can be read
///                                    * Bit[10:9]: Reserved
///                                    * Bit[11]: ac_en - Enables the auto color mode
///                                    ###
///               %%        20         # Stuffing bits...
///     @ 0x00004 STS0                 (R-)
///               ###
///               * AC_VAL_M
///               ###
///               %unsigned 8  VAL                       0x0
///               %%        24         # Stuffing bits...
///     @ 0x00008 STS1                 (R-)
///               ###
///               * {CMU_CHROMA_VAL_H,CMU_CHROMA_VAL_L}
///               ###
///               %unsigned 16 CHROMA_VAL_OUT            0x0
///               %%        16         # Stuffing bits...
///     @ 0x0000C STS2                 (R-)
///               ###
///               * {CMU_M_POINTS_3[4:0],CMU_M_POINTS_2,CMU_M_POINTS_1,CMU_M_POINTS_0}
///               ###
///               %unsigned 29 POINTS                    0x0
///                                    ###
///                                    * End of ac register group
///                                    ###
///               %%        3          # Stuffing bits...
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:      16B, bits:      65b, padding:     0B
////////////////////////////////////////////////////////////
