//////
/// 
/// $INTERFACE HS                      biu              (4,4)
///     ###
///     * Register specification of interface HS
///     * Defines the size of the hs
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 CFG0                 (P)
///               %unsigned 2  EN                        0x0
///                                    ###
///                                    * Bit[0]: en -
///                                    * 0 : Hue saturation adjustment for Main channel disabled
///                                    * 1 : Hue saturation adjustment for Main channel enabled
///                                    * Bit[1]: men -
///                                    * 0 : Intelligent saturation for Main channel disabled
///                                    * 1 : Intelligent saturation for Main channel enabled
///                                    ###
///               %unsigned 1  WG_EN                     0x0
///                                    ###
///                                    * Wide gamut Enable(Un used)=0
///                                    ###
///               %unsigned 1  WG_MODE                   0x0
///                                    ###
///                                    * Wide gamut Mode (Un Used)=0
///                                    ###
///               %unsigned 9  AX1                       0x0
///                                    ###
///                                    * Axes for the Main channel color wheel in terms of degrees. They must lie in the range 0 to 360 such that each successive axis is greater than or equal to the former.
///                                    ###
///               %unsigned 9  AX2                       0x10
///                                    ###
///                                    * Axes for the Main channel color wheel in terms of degrees. They must lie in the range 0 to 360 such that each successive axis is greater than or equal to the former.
///                                    ###
///               %unsigned 9  AX3                       0x23
///                                    ###
///                                    * Axes for the Main channel color wheel in terms of degrees. They must lie in the range 0 to 360 such that each successive axis is greater than or equal to the former.
///                                    ###
///               %%        1          # Stuffing bits...
///     @ 0x00004 CFG1                 (P)
///               %unsigned 9  AX4                       0x41
///                                    ###
///                                    * Axes for the Main channel color wheel in terms of degrees. They must lie in the range 0 to 360 such that each successive axis is greater than or equal to the former.
///                                    ###
///               %unsigned 9  AX5                       0x58
///                                    ###
///                                    * Axes for the Main channel color wheel in terms of degrees. They must lie in the range 0 to 360 such that each successive axis is greater than or equal to the former.
///                                    ###
